package com.primehr.learningdevelopment.completion.api;

import com.primehr.learningdevelopment.completion.api.LdCompletionDtos.*;
import com.primehr.learningdevelopment.completion.application.LdCompletionService;
import com.primehr.learningdevelopment.completion.domain.LdCompletionEvidence;
import com.primehr.security.*;
import jakarta.validation.Valid;
import org.springframework.core.io.InputStreamResource;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import java.time.LocalDate;
import java.util.List;

@RestController
@RequestMapping("/api/primehr/v1/learning-development")
public class LdCompletionController {
    private final LdCompletionService service;private final LdParticipationPermissionGuard permission;private final AgencyScopeResolver agency;
    public LdCompletionController(LdCompletionService service,LdParticipationPermissionGuard permission,AgencyScopeResolver agency){this.service=service;this.permission=permission;this.agency=agency;}
    private String agency(Authentication a){return agency.resolveAgencyId(a);}private static String actor(Authentication a){if(a==null||a.getName()==null||a.getName().isBlank())throw new org.springframework.security.access.AccessDeniedException("Authenticated employee identity is required");return a.getName();}

    @GetMapping("/completion-cases") public List<CompletionCaseResponse> cases(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){return service.cases(agency(a),actor(a),permission.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.ACCESS,token));}
    @GetMapping("/completion-cases/mine") public List<CompletionCaseResponse> mine(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.ACCESS,token);return service.mine(agency(a),actor(a));}
    @GetMapping("/completion-cases/{id}") public CompletionCaseResponse get(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@PathVariable String id){return service.get(agency(a),id,actor(a),permission.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.ACCESS,token));}
    @GetMapping("/completion-cases/{id}/mine") public CompletionCaseResponse getMine(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@PathVariable String id){permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.ACCESS,token);return service.getMine(agency(a),id,actor(a));}
    @PostMapping("/enrollments/{id}/completion-case") @ResponseStatus(HttpStatus.CREATED) public CompletionCaseResponse open(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody OpenCaseInput input){return service.open(agency(a),id,input,actor(a),permission.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.ADD,token),correlation);}
    @PutMapping("/completion-cases/{id}/attendance/{sessionId}") public CompletionCaseResponse attendance(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@PathVariable String sessionId,@Valid @RequestBody AttendanceInput input){return service.recordAttendance(agency(a),id,sessionId,input,actor(a),permission.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.EDIT,token),correlation);}
    @PostMapping("/completion-cases/{id}/outputs") @ResponseStatus(HttpStatus.CREATED) public CompletionCaseResponse output(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody OutputInput input){return service.addOutput(agency(a),id,input,actor(a),permission.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.EDIT,token),correlation);}
    @PostMapping("/completion-cases/{id}/outputs/{outputId}/{action:verify|waive}") public CompletionCaseResponse outputDecision(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@PathVariable String outputId,@PathVariable String action,@Valid @RequestBody OutputDecision input){return service.decideOutput(agency(a),id,outputId,input,"waive".equals(action),actor(a),permission.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.APPROVE,token),correlation);}

    @PostMapping(value="/completion-cases/{id}/evidence",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.CREATED)
    public EvidenceResponse upload(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@RequestParam LdCompletionEvidence.Type evidenceType,@RequestParam(required=false)String outputId,@RequestParam(required=false)String certificateNumber,@RequestParam(required=false)String certificateIssuer,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate certificateIssueDate,@RequestPart("file")MultipartFile file){return service.upload(agency(a),id,evidenceType,outputId,certificateNumber,certificateIssuer,certificateIssueDate,file,actor(a),permission.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.EDIT,token),false,correlation);}
    @PostMapping(value="/completion-cases/{id}/evidence/mine",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.CREATED)
    public EvidenceResponse uploadMine(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@RequestParam LdCompletionEvidence.Type evidenceType,@RequestParam(required=false)String outputId,@RequestParam(required=false)String certificateNumber,@RequestParam(required=false)String certificateIssuer,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate certificateIssueDate,@RequestPart("file")MultipartFile file){var scope=permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.ACCESS,token);return service.upload(agency(a),id,evidenceType,outputId,certificateNumber,certificateIssuer,certificateIssueDate,file,actor(a),scope,true,correlation);}
    @GetMapping("/completion-cases/{id}/evidence/{evidenceId}/content") public ResponseEntity<InputStreamResource> download(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@PathVariable String evidenceId){var value=service.download(agency(a),id,evidenceId,actor(a),permission.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.ACCESS,token),false,correlation);return content(value);}
    @GetMapping("/completion-cases/{id}/evidence/{evidenceId}/content/mine") public ResponseEntity<InputStreamResource> downloadMine(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@PathVariable String evidenceId){var scope=permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.ACCESS,token);return content(service.download(agency(a),id,evidenceId,actor(a),scope,true,correlation));}

    @PostMapping("/completion-cases/{id}/submit") public CompletionCaseResponse submit(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody CaseTransition input){return service.submit(agency(a),id,input,actor(a),permission.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.SUBMIT,token),correlation);}
    @PostMapping("/completion-cases/{id}/return") public CompletionCaseResponse returnForChanges(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody CaseTransition input){return service.returnForChanges(agency(a),id,input,actor(a),permission.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.FINALIZE,token),correlation);}
    @PostMapping("/completion-cases/{id}/finalize") public CompletionCaseResponse finalizeCase(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody CompletionDecision input){return service.finalizeCase(agency(a),id,input,actor(a),permission.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.FINALIZE,token),correlation);}

    private static ResponseEntity<InputStreamResource> content(EvidenceContent value){return ResponseEntity.ok().contentType(MediaType.parseMediaType(value.mediaType())).contentLength(value.size()).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(value.filename()).build().toString()).header(HttpHeaders.CACHE_CONTROL,"no-store").header("X-Content-Type-Options","nosniff").body(new InputStreamResource(value.stream()));}
}
